/*
 * C key-schedule + MAC test: asserts sn_kdf.c reproduces the golden vectors
 * (sn_vectors.h, generated by test/gen_sn_vectors.py from the spec repository's
 * shieldnet-protocol/vectors/shieldnet-v1-vectors.json). A
 * pass here plus a pass of the Go golden test is the byte-exact C<->Go agreement §15
 * requires; the vectors come from an independent Python implementation, so neither
 * side is self-referential.
 */
#include "shieldnet/sn_kdf.h"
#include "shieldnet/sn_wire.h"
#include "sn_vectors.h"

#include <sodium.h>
#include <stdio.h>
#include <string.h>

static int failures = 0;

static void chk(const char *name, const unsigned char *got,
                const unsigned char *want, size_t len) {
    if (memcmp(got, want, len) != 0) {
        printf("FAIL %s\n", name);
        failures++;
    } else {
        printf("ok   %s\n", name);
    }
}

int main(void) {
    if (sodium_init() < 0) {
        printf("sodium_init failed\n");
        return 2;
    }

    /* Derivation chain. */
    unsigned char k_dev[32], k_req[32], k_resp[32];
    sn_derive_kdev(sn_in_psk, sn_in_device_id, k_dev);
    sn_derive_static(k_dev, k_req, k_resp);
    chk("k_dev", k_dev, sn_want_k_dev, 32);
    chk("k_req", k_req, sn_want_k_req, 32);
    chk("k_resp", k_resp, sn_want_k_resp, 32);

    /* §15: a second PSK and a second device_id each give a different k_dev. */
    unsigned char k_dev_alt[32];
    sn_derive_kdev(sn_in_psk2, sn_in_device_id, k_dev_alt);
    chk("k_dev_psk2", k_dev_alt, sn_want_k_dev_psk2, 32);
    sn_derive_kdev(sn_in_psk, sn_in_device_id2, k_dev_alt);
    chk("k_dev_dev2", k_dev_alt, sn_want_k_dev_dev2, 32);

    /* Transport 3.2, second way: the one-shot provisioning helper derives the
     * vector k_dev and wipes the PSK buffer. */
    {
        unsigned char buf[32], out[32];
        memcpy(buf, sn_in_psk, 32);
        int rc = sn_provision_kdev(buf, sn_in_device_id, out);
        if (rc != 0) {
            printf("FAIL provision_kdev_vector returns 0\n");
            failures++;
        }
        chk("provision_kdev_vector", out, sn_want_k_dev, 32);
        /* All 32 octets: sn_in_psk[0] is already 0x00. */
        if (sodium_is_zero(buf, 32) == 1) {
            printf("ok   provision_kdev_wipes_psk\n");
        } else {
            printf("FAIL provision_kdev_wipes_psk\n");
            failures++;
        }

        memcpy(buf, sn_in_psk, 32);
        rc = sn_provision_kdev(buf, sn_in_device_id, buf);
        if (rc != 0) {
            printf("FAIL provision_kdev_in_place returns 0\n");
            failures++;
        }
        chk("provision_kdev_in_place", buf, sn_want_k_dev, 32);
    }

    /* Public keys from the private inputs must match the vectors. */
    unsigned char e_c[32], e_s[32];
    crypto_scalarmult_base(e_c, sn_in_e_c_priv);
    crypto_scalarmult_base(e_s, sn_in_e_s_priv);
    chk("e_c", e_c, sn_want_e_c, 32);
    chk("e_s", e_s, sn_want_e_s, 32);

    /* MACs. */
    unsigned char out16[16], out8[8];
    sn_init_mac(k_req, sn_in_client_nonce, sn_in_device_id, out16);
    chk("init_mac", out16, sn_want_init_mac, 16);

    sn_epoch_tag(sn_in_cookie_secret, sn_in_cookie_epoch_be, out8);
    chk("epoch_tag", out8, sn_want_epoch_tag_out, 8);

    sn_cookie(sn_in_cookie_secret, sn_in_epoch_tag, sn_in_canonical_source,
              sn_in_client_nonce, out16);
    chk("cookie", out16, sn_want_cookie_out, 16);

    sn_retry_mac(k_resp, sn_in_client_nonce, sn_in_epoch_tag, sn_in_cookie,
                 sn_in_admission_epoch, sn_in_device_id, sn_in_observed_source, out16);
    chk("retry_mac", out16, sn_want_retry_mac, 16);

    /* Transcript. */
    unsigned char context[65], context2[129];
    sn_context(sn_in_client_nonce, sn_in_epoch_tag, sn_in_cookie,
               sn_in_admission_epoch, sn_in_device_id, context);
    chk("context", context, sn_want_context, 65);
    sn_context2(context, e_c, e_s, context2);
    chk("context2", context2, sn_want_context2, 129);

    sn_client_tag(k_req, context, e_c, out16);
    chk("client_tag", out16, sn_want_client_tag, 16);
    sn_admit_pre(k_resp, context2, out16);
    chk("admit_pre", out16, sn_want_admit_pre, 16);

    /* Agreement + master + session keys. dh = X25519(e_c_priv, e_s). */
    unsigned char dh[32];
    if (sn_dh(sn_in_e_c_priv, e_s, dh) != 0) {
        printf("FAIL dh returned error\n");
        failures++;
    } else {
        chk("dh", dh, sn_want_dh, 32);
    }
    unsigned char master[32], kc2s[32], ks2c[32], kkc2s[32], kks2c[32];
    sn_master(context2, k_dev, dh, master);
    chk("master", master, sn_want_master, 32);
    sn_session_keys(master, kc2s, ks2c, kkc2s, kks2c);
    chk("k_c2s", kc2s, sn_want_k_c2s, 32);
    chk("k_s2c", ks2c, sn_want_k_s2c, 32);
    chk("k_kcp_c2s", kkc2s, sn_want_k_kcp_c2s, 32);
    chk("k_kcp_s2c", kks2c, sn_want_k_kcp_s2c, 32);
    sn_admit_tag(master, out16);
    chk("admit_tag", out16, sn_want_admit_tag, 16);

    /* The all-zero DH rejection: a low-order point yields -1. RFC 7748 order-8 point. */
    static const unsigned char low_order[32] = {
        0xe0,0xeb,0x7a,0x7c,0x3b,0x41,0xb8,0xae,0x16,0x56,0xe3,0xfa,0xf1,0x9f,0xc4,0x6a,
        0xda,0x09,0x8d,0xeb,0x9c,0x32,0xb1,0xfd,0x86,0x62,0x05,0x16,0x5f,0x49,0xb8,0x00 };
    unsigned char junk[32];
    if (sn_dh(sn_in_e_c_priv, low_order, junk) == 0) {
        printf("FAIL sn_dh accepted a low-order point\n");
        failures++;
    } else {
        printf("ok   dh rejects low-order point\n");
    }


    /* Wire messages: encode from the fixed fields and compare to the golden datagrams. */
    unsigned char init[SN_INIT_LEN], retry[SN_RETRY_LEN];
    unsigned char finish[SN_FINISH_LEN], admit[SN_ADMIT_LEN];
    sn_encode_init(sn_in_client_nonce, sn_in_device_id, sn_want_init_mac, init);
    chk("msg_init", init, sn_msg_init, SN_INIT_LEN);
    sn_encode_retry(sn_in_epoch_tag, sn_in_cookie, sn_in_admission_epoch,
                    sn_in_device_id, sn_in_observed_source, sn_want_retry_mac, retry);
    chk("msg_retry", retry, sn_msg_retry, SN_RETRY_LEN);
    sn_encode_finish(sn_in_client_nonce, sn_in_epoch_tag, sn_in_cookie,
                     sn_in_admission_epoch, e_c, sn_want_client_tag, finish);
    chk("msg_finish", finish, sn_msg_finish, SN_FINISH_LEN);
    sn_encode_admit(sn_in_admission_epoch, e_s, sn_want_admit_pre, sn_want_admit_tag, admit);
    chk("msg_admit", admit, sn_msg_admit, SN_ADMIT_LEN);

    /* Envelope: seal the fixed KCP message under k_kcp_c2s at the fixed seq_full and
     * compare the full datagram; then open it back. */
    unsigned char env[64]; size_t env_len = 0;
    if (sn_seal(kkc2s, 1, sn_in_seq_full, sn_in_kcp_msg, sizeof sn_in_kcp_msg, env, &env_len) != 0) {
        printf("FAIL sn_seal\n"); failures++;
    } else {
        chk("envelope", env, sn_want_envelope, env_len);
        unsigned char back[64]; size_t back_len = 0;
        if (sn_open(kkc2s, 1, sn_in_seq_full, env, env_len, back, &back_len) != 0
            || back_len != sizeof sn_in_kcp_msg
            || memcmp(back, sn_in_kcp_msg, back_len) != 0) {
            printf("FAIL envelope round trip\n"); failures++;
        } else {
            printf("ok   envelope round trip\n");
        }
    }

    /* The promoting PUSH envelope: c2s, seq_full 1, under k_kcp_c2s. It opens to
     * kcp_push, whose first segment is a PUSH (0x51) at sn 0 on kcp_conv. */
    {
        unsigned char pt[sizeof sn_want_envelope_push]; size_t pt_len = 0;
        int ok = sn_open(sn_want_k_kcp_c2s, 1, 1, sn_want_envelope_push,
                         sizeof sn_want_envelope_push, pt, &pt_len) == 0;
        ok = ok && pt_len == sizeof sn_in_kcp_push && memcmp(pt, sn_in_kcp_push, pt_len) == 0;
        if (!ok) {
            printf("FAIL envelope_push opens to kcp_push\n"); failures++;
        } else {
            printf("ok   envelope_push opens to kcp_push\n");
            unsigned long conv = (unsigned long)pt[0] | ((unsigned long)pt[1] << 8) |
                                 ((unsigned long)pt[2] << 16) | ((unsigned long)pt[3] << 24);
            unsigned long sn = (unsigned long)pt[12] | ((unsigned long)pt[13] << 8) |
                               ((unsigned long)pt[14] << 16) | ((unsigned long)pt[15] << 24);
            if (pt_len < 24 || pt[4] != 0x51 || sn != 0 || conv != sn_in_kcp_conv) {
                printf("FAIL envelope_push segment: cmd=0x%02x sn=%lu conv=0x%lx\n",
                       pt[4], sn, conv);
                failures++;
            } else {
                printf("ok   envelope_push segment (PUSH, sn 0, kcp_conv)\n");
            }
        }
    }

    /* §8.3 reconstruction cases from the vector file. */
    for (size_t i = 0; i < sizeof sn_recon / sizeof sn_recon[0]; i++) {
        int64_t got = sn_reconstruct(sn_recon[i].seq_wire, sn_recon[i].hwm);
        if (got != sn_recon[i].candidate) {
            printf("FAIL reconstruct[%zu]: got %lld want %lld\n",
                   i, (long long)got, sn_recon[i].candidate);
            failures++;
        } else {
            printf("ok   reconstruct[%zu]\n", i);
        }
    }

    if (failures) {
        printf("%d FAILURE(S)\n", failures);
        return 1;
    }
    printf("all vectors match\n");
    return 0;
}
